'use strict';
/* Public-domain classical repertoire for Concert Flute and Oboe.
 * Note format matches the recital host: [timeSec, durSec, midiPitch, velocity]. */
window.WOODWIND_SONGS = (() => {
  const NOTE = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };
  function midi(name) {
    const m = /^([A-G])([#b]?)(\d)$/.exec(name);
    return (Number(m[3]) + 1) * 12 + NOTE[m[1]] + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0);
  }
  function seq(bpm, items) {
    const spb = 60 / bpm, notes = [];
    let beat = 0;
    for (const it of items) {
      const [n, dur, vel = 82] = it;
      if (n !== 'R') notes.push([+(beat * spb).toFixed(4), +(dur * spb * 0.94).toFixed(4), typeof n === 'number' ? n : midi(n), vel]);
      beat += dur;
    }
    return { notes, duration: +(beat * spb + 0.8).toFixed(3) };
  }

  // ---- FLUTE REPERTOIRE ----
  // 1. J. S. Bach — Badinerie (BWV 1067, B minor, 2/4)
  const badinerieA = [
    ['B5', 0.25, 88], ['D6', 0.125, 84], ['B5', 0.125, 82],
    ['F#5', 0.25, 86], ['B5', 0.125, 84], ['F#5', 0.125, 80], ['D5', 0.25, 84], ['F#5', 0.125, 82], ['D5', 0.125, 78],
    ['B4', 0.5, 86], ['F#4', 0.25, 76], ['B4', 0.25, 80], ['D5', 0.25, 82], ['B4', 0.25, 80],
    ['C#5', 0.25, 82], ['B4', 0.25, 78], ['C#5', 0.25, 82], ['B4', 0.25, 78],
    ['A#4', 0.25, 84], ['C#5', 0.25, 82], ['F#5', 0.5, 90],
    ['B5', 0.25, 90], ['D6', 0.125, 86], ['B5', 0.125, 84],
    ['F#5', 0.25, 88], ['B5', 0.125, 86], ['F#5', 0.125, 82], ['D5', 0.25, 84], ['F#5', 0.125, 82], ['D5', 0.125, 80],
    ['B4', 0.25, 82], ['D5', 0.25, 84], ['G5', 0.25, 88], ['E5', 0.25, 84],
    ['C#5', 0.25, 84], ['E5', 0.25, 86], ['A5', 0.25, 90], ['F#5', 0.25, 86],
    ['D5', 0.125, 84], ['E5', 0.125, 84], ['F#5', 0.125, 86], ['G5', 0.125, 88], ['A5', 0.125, 90], ['B5', 0.125, 92], ['C#6', 0.125, 94], ['D6', 0.125, 96],
    ['B5', 0.25, 92], ['G5', 0.25, 86], ['E5', 0.25, 84], ['C#5', 0.25, 82],
    ['D5', 0.5, 88], ['F#5', 0.25, 84], ['A5', 0.25, 88],
    ['D6', 0.25, 94], ['C#6', 0.125, 90], ['B5', 0.125, 88], ['A5', 0.25, 88], ['G5', 0.125, 84], ['F#5', 0.125, 82],
    ['E5', 0.25, 86], ['G5', 0.125, 86], ['E5', 0.125, 82], ['C#5', 0.25, 82], ['E5', 0.125, 84], ['C#5', 0.125, 80],
    ['A4', 0.25, 80], ['C#5', 0.25, 84], ['E5', 0.25, 86], ['G5', 0.25, 88],
    ['F#5', 0.25, 88], ['E5', 0.125, 84], ['D5', 0.125, 82], ['C#5', 0.25, 84], ['B4', 0.25, 86],
  ];
  const badinerieB = [
    ['F#5', 0.25, 86], ['A5', 0.125, 86], ['F#5', 0.125, 84], ['D5', 0.25, 84], ['F#5', 0.125, 84], ['D5', 0.125, 80],
    ['A4', 0.5, 82], ['D5', 0.25, 84], ['F#5', 0.25, 86],
    ['G5', 0.25, 88], ['B5', 0.125, 90], ['G5', 0.125, 86], ['E5', 0.25, 86], ['G5', 0.125, 86], ['E5', 0.125, 82],
    ['C#5', 0.5, 84], ['E5', 0.25, 84], ['A5', 0.25, 88],
    ['B5', 0.125, 90], ['C#6', 0.125, 92], ['D6', 0.125, 94], ['E6', 0.125, 96], ['F#6', 0.25, 98], ['D6', 0.25, 92],
    ['B5', 0.25, 90], ['G#5', 0.25, 88], ['E5', 0.25, 84], ['B5', 0.25, 88],
    ['C#6', 0.25, 92], ['A#5', 0.25, 90], ['F#5', 0.25, 86], ['C#6', 0.25, 90],
    ['D6', 0.25, 94], ['B5', 0.25, 90], ['F#5', 0.25, 86], ['D5', 0.25, 84],
    ['E5', 0.125, 86], ['F#5', 0.125, 86], ['G5', 0.125, 88], ['E5', 0.125, 84], ['C#5', 0.25, 84], ['A#4', 0.25, 82],
    ['B4', 1.0, 92],
  ];
  const badinerie = seq(124, [...badinerieA, ...badinerieB, ...badinerieA.slice(0, 28), ['B4', 1.0, 90]]);

  // 2. C. W. Gluck — Dance of the Blessed Spirits (F major, 3/4)
  const gluck = seq(72, [
    ['A5', 1.5, 76], ['G5', 0.5, 74], ['F5', 1.0, 78],
    ['E5', 1.0, 74], ['D5', 0.5, 72], ['C5', 0.5, 72], ['D5', 1.0, 74],
    ['C5', 1.5, 74], ['Bb4', 0.5, 72], ['A4', 1.0, 70],
    ['G4', 2.0, 72], ['R', 1.0],
    ['C5', 1.0, 74], ['F5', 1.0, 80], ['A5', 1.0, 84],
    ['G5', 1.5, 82], ['F5', 0.5, 78], ['E5', 1.0, 76],
    ['D5', 1.0, 76], ['G5', 1.0, 82], ['Bb5', 1.0, 86],
    ['A5', 2.0, 84], ['G5', 1.0, 78],
    ['F5', 1.5, 80], ['E5', 0.5, 76], ['D5', 1.0, 74],
    ['C5', 1.0, 74], ['D5', 0.5, 76], ['E5', 0.5, 78], ['F5', 1.0, 80],
    ['G5', 1.5, 82], ['A5', 0.5, 84], ['Bb5', 1.0, 86],
    ['A5', 1.5, 84], ['G5', 0.5, 80], ['F5', 1.0, 78],
    ['E5', 1.0, 74], ['F5', 0.5, 76], ['G5', 0.5, 78], ['A5', 1.0, 82],
    ['G5', 1.0, 78], ['F5', 1.0, 76], ['E5', 1.0, 74],
    ['F5', 3.0, 80],
  ]);

  // 3. C. Debussy — Syrinx (L. 129, Bb minor / chromatic, 3/4)
  const syrinx = seq(54, [
    ['Bb5', 1.0, 76], ['A5', 0.25, 74], ['B5', 0.25, 76], ['A5', 0.5, 74], ['Gb5', 0.25, 72], ['Ab5', 0.25, 74], ['Gb5', 0.5, 72],
    ['F5', 1.5, 74], ['E5', 0.25, 72], ['F#5', 0.25, 74], ['E5', 0.5, 72], ['Db5', 0.5, 70],
    ['Bb4', 1.5, 72], ['R', 0.5], ['Db5', 0.5, 72], ['Eb5', 0.5, 74],
    ['F5', 1.0, 78], ['Gb5', 0.5, 80], ['Ab5', 0.5, 82], ['Bb5', 1.0, 86],
    ['C6', 0.5, 88], ['Db6', 0.5, 90], ['Bb5', 1.0, 84], ['Ab5', 0.5, 80], ['Gb5', 0.5, 78],
    ['F5', 1.5, 76], ['Eb5', 0.5, 74], ['Db5', 1.0, 72],
    ['Bb4', 1.0, 70], ['C5', 0.5, 72], ['Db5', 0.5, 74], ['Eb5', 0.5, 76], ['F5', 0.5, 78],
    ['Gb5', 1.0, 80], ['Ab5', 1.0, 82], ['Bb5', 1.0, 84],
    ['Ab5', 0.5, 78], ['Gb5', 0.5, 76], ['F5', 0.5, 74], ['Eb5', 0.5, 72], ['Db5', 1.0, 70],
    ['C5', 0.75, 68], ['Bb4', 0.25, 66], ['Db5', 2.0, 72],
  ]);

  // ---- OBOE REPERTOIRE ----
  // 1. A. Marcello — Oboe Concerto in D minor, 2nd mvt Adagio (3/4)
  const marcello = seq(56, [
    ['R', 1.0], ['A5', 1.5, 82], ['G5', 0.25, 78], ['F5', 0.25, 76],
    ['E5', 1.0, 80], ['D5', 0.5, 78], ['C#5', 0.5, 76], ['D5', 1.0, 80],
    ['E5', 1.5, 82], ['F5', 0.25, 82], ['G5', 0.25, 84], ['F5', 0.5, 80], ['E5', 0.5, 78],
    ['D5', 1.5, 80], ['C#5', 0.5, 76], ['A4', 1.0, 74],
    ['F5', 1.5, 84], ['E5', 0.25, 80], ['D5', 0.25, 78], ['C5', 1.0, 78],
    ['Bb4', 1.0, 76], ['A4', 0.5, 74], ['G4', 0.5, 72], ['A4', 1.0, 76],
    ['Bb4', 1.0, 78], ['C5', 0.5, 80], ['D5', 0.5, 82], ['E5', 0.5, 84], ['F5', 0.5, 86],
    ['G5', 1.5, 88], ['F5', 0.5, 84], ['E5', 1.0, 82],
    ['A5', 1.0, 88], ['Bb5', 0.5, 90], ['A5', 0.5, 86], ['G5', 0.5, 84], ['F5', 0.5, 82],
    ['E5', 1.0, 82], ['F5', 0.5, 80], ['D5', 0.5, 78], ['C#5', 1.0, 78],
    ['D5', 1.5, 80], ['E5', 0.25, 80], ['F5', 0.25, 82], ['E5', 0.5, 78], ['D5', 0.5, 76],
    ['C#5', 1.0, 76], ['D5', 2.0, 82],
  ]);

  // 2. J. S. Bach — Sinfonia from Cantata BWV 156 (Arioso, F major, 4/4)
  const arioso = seq(58, [
    ['A5', 2.0, 82], ['G5', 0.5, 78], ['F5', 0.5, 78], ['E5', 0.5, 76], ['D5', 0.5, 76],
    ['C5', 1.5, 78], ['D5', 0.25, 76], ['E5', 0.25, 78], ['F5', 1.0, 82], ['G5', 1.0, 84],
    ['A5', 1.0, 86], ['Bb5', 0.5, 88], ['A5', 0.5, 84], ['G5', 0.5, 82], ['F5', 0.5, 80], ['E5', 0.5, 78], ['D5', 0.5, 76],
    ['C5', 2.0, 78], ['R', 0.5], ['C5', 0.5, 76], ['D5', 0.5, 78], ['E5', 0.5, 80],
    ['F5', 1.5, 84], ['G5', 0.5, 86], ['A5', 1.0, 88], ['Bb5', 1.0, 90],
    ['C6', 1.5, 92], ['Bb5', 0.5, 88], ['A5', 1.0, 86], ['G5', 1.0, 82],
    ['F5', 1.0, 80], ['E5', 0.5, 78], ['D5', 0.5, 76], ['C5', 1.0, 76], ['Bb4', 0.5, 74], ['A4', 0.5, 72],
    ['G4', 1.0, 74], ['A4', 0.5, 76], ['Bb4', 0.5, 78], ['C5', 1.0, 80], ['E5', 1.0, 82],
    ['F5', 3.0, 84],
  ]);

  // 3. W. A. Mozart — Oboe Quartet in F major, K. 370 (1st mvt Allegro, 4/4)
  const mozart = seq(116, [
    ['C6', 1.5, 88], ['A5', 0.5, 84], ['F5', 1.0, 82], ['C5', 1.0, 80],
    ['D5', 0.5, 80], ['E5', 0.5, 82], ['F5', 0.5, 84], ['G5', 0.5, 86], ['A5', 1.0, 88], ['G5', 1.0, 84],
    ['F5', 0.5, 82], ['E5', 0.5, 80], ['D5', 0.5, 80], ['C5', 0.5, 78], ['Bb4', 1.0, 80], ['G4', 1.0, 78],
    ['A4', 0.5, 78], ['C5', 0.5, 80], ['F5', 0.5, 84], ['A5', 0.5, 88], ['G5', 2.0, 86],
    ['C6', 1.5, 90], ['Bb5', 0.5, 86], ['A5', 0.5, 84], ['G5', 0.5, 82], ['F5', 0.5, 80], ['E5', 0.5, 80],
    ['D5', 0.5, 82], ['F5', 0.5, 84], ['Bb5', 0.5, 88], ['D6', 0.5, 92], ['C6', 1.0, 90], ['A5', 1.0, 86],
    ['G5', 0.5, 84], ['A5', 0.5, 86], ['Bb5', 0.5, 88], ['G5', 0.5, 84], ['F5', 0.5, 82], ['G5', 0.5, 84], ['A5', 0.5, 86], ['F5', 0.5, 82],
    ['E5', 0.5, 80], ['F5', 0.5, 82], ['G5', 0.5, 84], ['E5', 0.5, 80], ['C5', 1.0, 80], ['R', 1.0],
    ['F5', 0.5, 82], ['A5', 0.5, 86], ['C6', 1.0, 90], ['Bb5', 0.5, 86], ['G5', 0.5, 82], ['E5', 1.0, 80],
    ['F5', 2.0, 88],
  ]);

  const makeSong = (id, title, composer, opus, bpm, fifths, numerator, denominator, data) => ({
    id, title, composer, opus, bpm,
    duration: data.duration,
    notes: data.notes,
    tempos: [{ time: 0, beat: 0, bpm }],
    signatures: [{ beat: 0, numerator, denominator }],
    keySignature: { fifths },
    keySignatures: [{ beat: 0, fifths }],
  });

  return {
    flute: [
      makeSong('badinerie', 'Badinerie', 'Johann Sebastian Bach', 'Suite No. 2, BWV 1067', 124, 2, 2, 4, badinerie),
      makeSong('blessed-spirits', 'Dance of the Blessed Spirits', 'Christoph Willibald Gluck', 'Orfeo ed Euridice', 72, -1, 3, 4, gluck),
      makeSong('syrinx', 'Syrinx', 'Claude Debussy', 'L. 129', 54, -5, 3, 4, syrinx),
    ],
    oboe: [
      makeSong('marcello-adagio', 'Oboe Concerto — Adagio', 'Alessandro Marcello', 'in D minor, S.Z799', 56, -1, 3, 4, marcello),
      makeSong('bach-arioso', 'Sinfonia (Arioso)', 'Johann Sebastian Bach', 'Cantata BWV 156', 58, -1, 4, 4, arioso),
      makeSong('mozart-quartet', 'Oboe Quartet in F', 'Wolfgang Amadeus Mozart', 'K. 370 — Allegro', 116, -1, 4, 4, mozart),
    ],
  };
})();
